#include <stop_token>
#include <thread>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::stop_source source;
    auto token = source.get_token();
    std::stop_token copy;
    copy = token;
    assert(copy == token);
    std::stop_source other{std::nostopstate};
    std::nostopstate_t tag = std::nostopstate;
    (void)tag;
    assert(!other.stop_possible() && source.stop_possible());
    other = source;
    source.swap(other);
    std::swap(source, other);
    copy.swap(token);
    std::swap(copy, token);
    int calls = 0;
    {
        std::stop_callback callback{token, [&] { ++calls; }};
        assert(source.request_stop());
        assert(calls == 1);
    }
    assert(token.stop_requested() && source.stop_requested());
    std::jthread worker(
        [](std::stop_token request) { (void)request.stop_requested(); });
    std::jthread moved;
    moved = std::move(worker);
}
